def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {}
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive[agent_id] = opp

    if not alive:
        return min(float(budget), 18.0)

    prev_bids = []
    max_prev_bid = 0.0
    bob_prev_bid = None
    desperate_count = 0
    rich_alive = 0

    for agent_id, opp in alive.items():
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_alive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > max_prev_bid:
                max_prev_bid = float(bid)
            if agent_id == 'Bob':
                bob_prev_bid = float(bid)

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    alive_count = len(alive)
    contested = alive_count + 1 > slots

    base = 20.0

    if not contested:
        base = 8.0
    else:
        if slots >= 2:
            base = 24.0
        else:
            base = 42.0

    if max_prev_bid >= 80:
        base = max(base, 50.0)
    elif max_prev_bid >= 65:
        base = max(base, 38.0)
    elif max_prev_bid > 0:
        base = max(base, min(36.0, max_prev_bid * 0.58))

    if bob_prev_bid is not None:
        if bob_prev_bid >= 80:
            base = max(base, 52.0)
        elif bob_prev_bid >= 70:
            base = max(base, 40.0)

    if supply <= 16:
        base += 16.0
    elif supply <= 18:
        base += 8.0
    elif supply >= 24:
        base -= 6.0

    if hp <= 2:
        base = max(base, 66.0)
    elif hp <= 4:
        base = max(base, 52.0)
    elif no_water >= 1:
        base = max(base, 48.0)

    if desperate_count >= 2:
        base += 8.0
    if rich_alive == 0:
        base -= 6.0

    if day >= 8 and hp >= 5:
        base -= 4.0

    reserve = 0.0
    if hp >= 5:
        reserve = 20.0
    elif hp >= 3:
        reserve = 10.0

    affordable = float(budget) - reserve
    if affordable < 0:
        affordable = float(budget)

    bid = min(base, affordable)
    if bid < 0:
        bid = 0.0
    if hp <= 2 and budget > 0:
        bid = max(bid, min(float(budget), 66.0))

    return float(min(float(budget), bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no opponents alive, conserve.
    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace to infer aggressiveness.
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Identify if someone is a known high spender (likely Cindy from trace patterns).
    high_spender = False
    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev >= 0.95 * 150.0:
            high_spender = True

    # Decide urgency based on hp/no_water_days.
    # If we're in danger, bid more to secure water.
    danger = (hp <= 2.0) or (no_water_days >= 2) or (hp <= 3.0 and no_water_days >= 1)

    # Supply pressure: lower supply means higher chance of contest; raise bid slightly.
    # Map supply in [15,25] to a multiplier in [1.15, 0.95].
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = max(0.0, min(1.0, float(t)))
    supply_mult = 1.15 - 0.20 * t

    # Estimate how much to bid relative to others.
    # Since Cindy appears to bid extremely high to survive, we avoid mirroring her max.
    # Instead, target winning against low/mid bidders: around 0.6-0.75 of DAILY_SALARY when safe,
    # and 0.85-0.95 when in danger.
    if danger:
        base = DAILY_SALARY * 0.9
    else:
        base = DAILY_SALARY * 0.65

    # If there is a very high spender, slightly reduce to avoid wasting budget.
    if high_spender:
        base *= 0.92

    bid = base * supply_mult

    # Budget cap and non-negative.
    bid = max(0.0, min(budget, bid))

    # If budget is tiny, still bid what we can.
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    base_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.8
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.4

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] < 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 3 and my_status['hp'] >= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.6)

    current_supply = day_context['supply']
    total_water_demand_estimate = WATER_REQ
    for opp in alive_opponents:
        total_water_demand_estimate += opp['water_requirement']

    if current_supply < total_water_demand_estimate:
        base_bid *= 1.2
    elif current_supply >= total_water_demand_estimate * 1.5:
        base_bid *= 0.8

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        lowest_prev_bid = min(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 5:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = min(base_bid, highest_prev_bid * 0.7)
        elif highest_prev_bid > base_bid * 1.1:
             base_bid = max(base_bid, highest_prev_bid + 2)
        elif lowest_prev_bid < base_bid * 0.7 and my_status['hp'] > 5:
            base_bid = min(base_bid, lowest_prev_bid + 1)

    final_bid = min(my_status['budget'], max(1.0, base_bid))

    for opp_id, opp_data in opponents_status.items():
        if opp_id == "Bob" and opp_data['alive']:
            bob_prev_trace = opp_data.get('previous_trace', {})
            if bob_prev_trace and bob_prev_trace.get('bid') is not None:
                if bob_prev_trace['bid'] >= DAILY_SALARY * 0.7:
                    final_bid = max(final_bid, DAILY_SALARY * 0.75)

    return final_bid
